CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', headline text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', about text NOT NULL DEFAULT '', skills text[] NOT NULL DEFAULT '{}', experience text NOT NULL DEFAULT '', education text NOT NULL DEFAULT '', cover_text text NOT NULL DEFAULT 'DIY OR DIE', open_to_work boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TYPE public.app_role AS ENUM ('candidate','organiser');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.choose_account_role(chosen public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),chosen) ON CONFLICT(user_id) DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.choose_account_role(public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.choose_account_role(public.app_role) TO authenticated;
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'name','')); RETURN NEW; END; $$;
CREATE TRIGGER create_app_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(trim(title)) > 0), description text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, field text NOT NULL DEFAULT 'General', qualities text[] NOT NULL DEFAULT '{}', published boolean NOT NULL DEFAULT false, CHECK(ends_at > starts_at));
GRANT SELECT ON public.events TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.events TO authenticated;
GRANT ALL ON public.events TO service_role;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_events ON public.events FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY own_event_read ON public.events FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY event_create ON public.events FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND (NOT published OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='organiser')));
CREATE POLICY event_update ON public.events FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid() AND (NOT published OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='organiser')));
CREATE POLICY event_delete ON public.events FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE INDEX events_owner_idx ON public.events(owner_id);
CREATE INDEX events_starts_idx ON public.events(starts_at);